import { format, addDays, isBefore } from "date-fns";

const today = new Date();
const nextWeek = addDays(today, 7);
const isPast = isBefore(nextWeek, today);
const dateStr = format(today, "yyyy-MM-dd");

import {
  format,
  parseISO,
  addDays,
  differenceInDays,
  isAfter,
} from "date-fns";

const created = parseISO("2024-05-01T10:00:00Z");

format(created, "yyyy-MM-dd");            // "2024-05-01"

const due = addDays(created, 7);

differenceInDays(due, created);           // 7

isAfter(due, new Date());                 // boolean

import { formatInTimeZone } from "date-fns-tz";
import { fr } from "date-fns/locale";

formatInTimeZone(
  new Date(),
  "Europe/London",
  "yyyy-MM-dd HH:mm zzz",
); // "2024-05-01 14:00 BST"

format(new Date(), "PPPP", { locale: fr }); // "1 mai 2024"
